def calculate(expression):
    parts = expression.strip().split()
    if len(parts) != 3:
        raise ValueError('Format: number operator number')
    a, op, b = float(parts[0]), parts[1], float(parts[2])
    ops = {'+': a+b, '-': a-b, '*': a*b, '/': a/b, '**': a**b}
    if op not in ops:
        raise ValueError(f'Unknown operator: {op}')
    return ops[op]

while True:
    expr = input('> ')
    if expr == 'quit': break
    print(calculate(expr))

import json
from dataclasses import dataclass, asdict
from pathlib import Path

@dataclass
class Task:
    id: int
    title: str
    done: bool = False

def load_tasks(path='tasks.json'):
    if Path(path).exists():
        return [Task(**t) for t in json.loads(Path(path).read_text())]
    return []

def save_tasks(tasks, path='tasks.json'):
    Path(path).write_text(json.dumps([asdict(t) for t in tasks]))

