class Expense:
    amount: float
    category: str
    date: str
    note: str = ''

def monthly_summary(expenses):
    totals = defaultdict(float)
    for e in expenses:
        totals[e.category] += e.amount
    return dict(totals)

from pathlib import Path
import shutil

EXT_MAP = {
    'Images': ['.jpg','.jpeg','.png','.gif','.svg'],
    'Documents': ['.pdf','.docx','.txt','.md'],
    'Code': ['.py','.js','.ts','.html','.css'],
    'Archives': ['.zip','.tar','.gz'],
}

def organize(folder: str, dry_run=False):
    src = Path(folder)
    ext_to_folder = {e: f for f, exts in EXT_MAP.items() for e in exts}
    for file in src.iterdir():
        if file.is_file():
            dest_name = ext_to_folder.get(file.suffix.lower(), 'Other')
            dest = src / dest_name
            if not dry_run:
                dest.mkdir(exist_ok=True)
                shutil.move(str(file), dest / file.name)
            print(f'{file.name} -> {dest_name}/')

