import chromadb
from openai import OpenAI

client = OpenAI()
chroma = chromadb.Client()
collection = chroma.create_collection('docs')

def embed(text):
    return client.embeddings.create(
        input=text, model='text-embedding-3-small'
    ).data[0].embedding

def add_doc(doc_id, text):
    collection.add(documents=[text], ids=[doc_id],
                   embeddings=[embed(text)])

def query(question, top_k=3):
    results = collection.query(query_embeddings=[embed(question)], n_results=top_k)
    context = '\n'.join(results['documents'][0])
    prompt = f'Context:\n{context}\n\nQuestion: {question}\nAnswer:'
    return client.chat.completions.create(
        model='gpt-4o-mini',
        messages=[{'role':'user','content':prompt}]
    ).choices[0].message.content

from openai import OpenAI
client = OpenAI()

def agent(system, user_message, model='gpt-4o-mini'):
    return client.chat.completions.create(
        model=model,
        messages=[
            {'role': 'system', 'content': system},
            {'role': 'user', 'content': user_message}
        ]
    ).choices[0].message.content

PLANNER = 'You are a software architect. Break tasks into numbered implementation steps.'
CODER   = 'You are a senior Python developer. Write clean, well-commented code.'
REVIEWER = 'You are a code reviewer. Find bugs, suggest improvements, rate the code 1-10.'

def review_pipeline(task):
    plan   = agent(PLANNER, task)
    code   = agent(CODER, f'Implement this plan:\n{plan}')
    review = agent(REVIEWER, f'Review this code:\n{code}')
    return {'plan': plan, 'code': code, 'review': review}
